#[test]
fn dp_encoders_match_fixtures() {
    let f = fixtures();
    assert_eq!(dp::rgb_to_hsv([255, 0, 0]), (0, 1000, 1000));
    assert_eq!(hex::encode(dp::dp24_value((0, 1000, 1000))), f["dp24_value_hex"].as_str().unwrap());

    let strip_map: Vec<u8> = vec![1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4];
    let dp61 = dp::dp61_value(
        &[(0, 1000, 1000), (120, 1000, 1000), (240, 1000, 1000), (0, 0, 1000)],
        &strip_map,
        false,
    );
    assert_eq!(hex::encode(dp61), f["dp61_value_hex"].as_str().unwrap());
}

#[test]
fn online_beacon_parses() {
    let f = fixtures();
    let beacon = hx(&f, "online_beacon_hex");
    let dev_id = f["dev_id"].as_str().unwrap();
    let key: [u8; 16] = [
        108, 30, 200, 226, 187, 155, 181, 154, 181, 11, 13, 175, 100, 155, 65, 10,
    ];
    let gw = frame::parse_online_report(&beacon, &key).expect("beacon parse");
    assert_eq!(gw, dev_id);
}

#[test]
fn reply_frame_parses_and_decrypts() {
    // Risposta device: header(4) + add(22, col child mate_id a [14..18]) + nonce(12)
    // + len(4) + cipher + tag(16) + tail(4). L'add viene cifrato come AAD.
    let f = fixtures();
    let session = hx(&f, "session_key_hex");
    let nonce = arr12(&f, "nonce_hex");
    let main_mate = arr4(&f, "main_mate_id_hex");
    let mate_id = arr4(&f, "child_mate_id_hex");
    let value = hx(&f, "dp24_value_hex");

    let add = frame::build_add(frame::PutType::ConsultResponse, 1, 2, &mate_id, value.len() as u32 + 24);
    let (ct, tag) = crypto::gcm_encrypt(&session, &nonce, &add, &value);

    let len_hex = lscbridge::util::pad_hex(4, &format!("{:x}", ct.len()), false);
    let mut fr = Vec::new();
    fr.extend_from_slice(&frame::HEADER);
    fr.extend_from_slice(&add);
    fr.extend_from_slice(&nonce);
    fr.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]); // id (ignorato)
    fr.extend_from_slice(&hex::decode(len_hex).unwrap());
    fr.extend_from_slice(&ct);
    fr.extend_from_slice(&tag);
    fr.extend_from_slice(&frame::TAIL);

    let (m, c, t) = frame::parse_reply(&fr).expect("parse");
    assert_eq!(m, mate_id);
    assert_eq!(frame::reply_nonce(&fr).unwrap(), nonce);
    let add_back = frame::reply_add(&fr).unwrap();
    let pt = crypto::gcm_decrypt(&session, &fr[26..38], &add_back, &c, &t).expect("decrypt");
    assert_eq!(pt, value);
}
